"""Compare historical 256 MiB and fresh 512 MiB diagnostic counts, never timings."""
import argparse
from collections import Counter
import hashlib
import json
from pathlib import Path


def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--output', type=Path, required=True)
    args = parser.parse_args()
    here = Path(__file__).resolve().parent
    root = here.parents[2]
    old = root / 'result-coordinate-evidence/compact-page-followup/diagnostic/runs/original'
    fresh_file = here / 'independent-discovery-original512.json'
    fresh = json.loads(fresh_file.read_text())
    assert fresh['valid'] and fresh['queryLimitBytes'] == 536870912
    sources = {str(fresh_file): sha(fresh_file), str(old / 'samples.jsonl'): sha(old / 'samples.jsonl')}
    raw = [json.loads(line) for line in (old / 'samples.jsonl').read_text().splitlines()]
    metadata, samples = raw[0], raw[1:]
    assert len(samples) == 4 and metadata['perQueryLedgerLimitBytes'] == 268435456
    assert metadata['projectedNames'] == ['s', 'a', 'l0', 'l1', 'r0', 'r1']
    assert metadata['canonicalGraphSha256'] == '59218d96a3c4c1cd3a2634c72174b0f44f3a7415d6cae4c944b1a54ed9506621'
    assert metadata['querySha256'] == '570d85a6fd11ecabae385744a2137f45aad5c9e53bf74dd50b2de69f3c2a4b76'
    comparisons = []
    for index, (sample, current) in enumerate(zip(samples, fresh['fixtures']['shared-tail']['queries'], strict=True)):
        page_file = old / 'page-records' / f'owner-{index + 1}.jsonl'
        sources[str(page_file)] = sha(page_file)
        records = [json.loads(line) for line in page_file.read_text().splitlines()]
        pages = [r for r in records if r['type'] == 'factor-page']
        summaries = [r for r in records if r['type'] == 'factor-page-summary']
        assert len(summaries) == 1 and len(records) == len(pages) + 1
        summary = summaries[0]
        assert summary['owner'] == index + 1 and summary['snapshotQueryLimitBytes'] == 268435456
        assert summary['pagesRetiredByNamespace'] == summary['pagesClearedBeforeFinalClose'] == 0
        counts = Counter(p['target'] for p in pages)
        assert summary['pageAdmissions'] == summary['pageReleases'] == len(pages)
        assert summary['admissionsByTarget'] == [counts[i] for i in range(6)]
        page_bytes = sum(p['baseReservationBytesAtSnapshot'] for p in pages)
        assert page_bytes == summary['baseBytesGranted'] == summary['baseBytesObservedBeforeRelease']
        assert sample['iteration'] == current['iteration'] and sample['stage'] == current['stage']
        assert sample['rows'] == current['rows'] == 1048576
        assert sample['checksum'] == current['checksum'] == '8327963502356915200'
        assert sample['valid'] and sample['exactBagValid'] and sample['ledgerBeforeBytes'] == sample['ledgerAfterBytes'] == 0
        previous = {'resolverCalls': sample['counters']['lazyValueCalls'], 'ordinaryHits': summary['ordinaryCacheHits'],
            'factorHits': summary['factorHits'], 'pageAdmissions': len(pages), 'pageChargeBytes': page_bytes,
            'pageAdmissionRefusals': summary['baseReservationRefusals'], 'ledgerPeakBytes': sample['ledgerPeakBytes']}
        now = {'resolverCalls': current['resolverCalls'], 'ordinaryHits': current['totals']['ordinaryHit'],
            'factorHits': current['totals']['factorHit'], 'pageAdmissions': current['distinctPageKeys'],
            'pageChargeBytes': current['pageChargeBytes'], 'pageAdmissionRefusals': current['totals']['pageRefused'],
            'ledgerPeakBytes': current['ledgerPeakBytes']}
        assert previous['ordinaryHits'] + previous['factorHits'] + previous['resolverCalls'] == 6291456
        comparisons.append({'iteration': current['iteration'], 'stage': current['stage'], 'historical256': previous,
            'fresh512': now, 'freshMinusHistorical': {k: now[k] - previous[k] for k in now}})
    record = {'format': 1, 'valid': True, 'scriptSha256': sha(__file__), 'sourceFiles': sources,
        'comparisons': comparisons, 'performanceInference': False, 'javaProcessesLaunched': 0,
        'interpretation': 'Same fixture identities and original dense materializer, but different isolated diagnostic instrumentation. These counts support the budget-confounding rationale; the new same-overlay 256/512 diagnostics are the definitive controlled comparison. No durations or allocations are compared.'}
    with args.output.open('x') as stream:
        json.dump(record, stream, indent=2, sort_keys=True)
        stream.write('\n')
    print(json.dumps({'valid': True, 'queriesCompared': len(comparisons), 'observedQuery': comparisons[-1],
                      'performanceInference': False, 'output': str(args.output)}))


if __name__ == '__main__':
    main()
